from lib import *
S = SS('v42')
steps = [
    step("断线重连不丢事件。watcher 监听前缀,收到 10 个事件后断开,断开的 2 秒里又写入 50 个 key,然后重连。(a) 不带 start_revision(从现在开始):断开前收到 10 个,重连后只收到 1 个(重连后才写的那个),整个过程 61 个 key 里有 50 个没收到,永远丢了。(b) start_revision = 最后看到的 revision + 1:断开前 10 个,重连后收到 51 个(断开期间的 50 个加重连后的 1 个),0 / 61 没收到,0 个重复。", t=tl(S(1)), mark=lidx(S(1), '(a)'), done=lidx(S(1), '(b)'), b=bars([['(a) 没收到的 key', 50, '50 / 61'], ['(b) 没收到的 key', 0, '0 / 61'], ['(b) 重连后收到', 51, '51(含断开期间 50 个)'], ['重复收到的 key', 0, '0']], 61, mark=[0], done=[1, 2, 3]), kv=KV([['(a) 从现在开始', '丢 50 个事件'], ['(b) 最后 revision + 1', '一个不丢,没有重复']], ['(a) 从现在开始'])),
    step("历史被压缩之后。写入 200 个版本的同一个 key,当前 revision 是 323,compact 到 313。(a) 从被压缩掉的旧 revision 263 watch:创建后立刻被取消,canceled = true,响应里带 compact_revision = 313,收到 0 个事件。(b) 从 compact revision 313 watch:创建成功,收到 313 到 323 共 11 个事件。(c) 从 314 watch:创建成功,收到 314 到 323 共 10 个事件。比 compact revision 小的历史取不到,客户端遇到这种取消必须重新 list 拿到当前全量和 header.revision,再从 header.revision + 1 开始 watch。", t=tl(S(2)), mark=lidx(S(2), '(a)'), done=lidx(S(2), '(b)', '(c)'), b=bars([['(a) 旧 revision 263:收到事件', 0, '0(被取消,compact_revision=313)'], ['(b) 313:收到事件', 11, '11(313…323)'], ['(c) 314:收到事件', 10, '10(314…323)']], 11, mark=[0], done=[1, 2]), kv=KV([['start_revision < compact', '创建后立刻 canceled,告知 compact_revision'], ['start_revision ≥ compact', '正常创建,补发历史事件']], ['start_revision < compact'])),
    step("事件的原子性与顺序,带 prev_kv。一个 Txn 同时 put 3 个 key:watcher 收到 1 个响应、3 个事件,mod_revision 都是 324。对前缀 delete range 删 3 个 key:1 个响应、3 个 DELETE 事件,revision 都是 325,prev_kv 的旧值是 1 1 1。第一次 put /tx/z:revision 326,没有旧值。第二次 put /tx/z:revision 327,prev_kv 旧值是 old。一次提交的多个修改在同一个 revision、同一个 watch 响应里到达;prev_kv 让 watcher 拿到修改前的值。", t=tl(S(3)), mark=lidx(S(3), 'DELETE'), done=lidx(S(3), 'PUT:/tx/a0', 'PUT:/tx/z'), b=bars([['Txn 3 个 put:事件数 / 响应', 3, '3 个事件 · 1 个响应 · revision 324'], ['delete range 3 个 key:事件数', 3, '3 个 DELETE · revision 325'], ['第二次 put /tx/z 的 prev_kv', 1, 'old']], 3, mark=[1], done=[0, 2]), kv=KV([['Txn(3 个 put)', '同一个 revision 324,一个响应'], ['delete range', '3 个 DELETE 事件,revision 325,prev_kv 1 1 1'], ['prev_kv', '修改前的值']], ['Txn(3 个 put)'])),
    step("有多少 watcher 时事件多久送到。1 / 50 / 200 个 watcher 监听同一个前缀(每个一条 HTTP 流连接),每 100 ms put 一次共 30 次,记录从 put 返回到每个 watcher 收到事件的延迟。1 个 watcher:收到 30 个事件,p50 6.58 ms,p99 9.23 ms,最大 9.40 ms。50 个:1500 个事件,p50 7.69 ms,p99 17.97 ms,最大 18.63 ms。200 个:6000 个事件,p50 14.40 ms,p99 22.11 ms,最大 22.83 ms。事件一个不少,延迟随 watcher 数缓慢增长;延迟里包含 HTTP 网关和 Python 线程调度的开销,不是 etcd 本身。", t=tl(S(4)), mark=lidx(S(4), '200 '), done=lidx(S(4), '1  ', '50 '), b=bars([['1 个 watcher:p50 ms', 6.58, '6.58'], ['50 个:p50 ms', 7.69, '7.69'], ['200 个:p50 ms', 14.40, '14.40'], ['200 个:p99 ms', 22.11, '22.11']], 23, done=[0, 1], mark=[2, 3]), kv=KV([['1 个 watcher', 'p50 6.58 ms,p99 9.23 ms'], ['200 个 watcher', 'p50 14.40 ms,p99 22.11 ms'], ['事件数', '每个 watcher 30 个,一个不少']], ['200 个 watcher'])),
]
